import mongoose from 'mongoose';

export const MAX_MESSAGE_LENGTH = 1000;

const messageSchema = new mongoose.Schema(
  {
    chatId: { type: mongoose.Schema.Types.ObjectId, ref: 'Chat', required: true },
    sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
    text: {
      type: String,
      required: [true, 'Message is empty'],
      trim: true,
      maxlength: [MAX_MESSAGE_LENGTH, `Message is too long (max ${MAX_MESSAGE_LENGTH})`],
    },
    // Generated by the client; lets a retried send be recognised instead of duplicated.
    clientId: { type: String, maxlength: 64 },
    deletedAt: Date,
  },
  { timestamps: { createdAt: true, updatedAt: false } }
);

// Newest-first paging within a chat.
messageSchema.index({ chatId: 1, _id: -1 });
// One message per (sender, clientId). Only applies when a clientId is present.
messageSchema.index(
  { sender: 1, clientId: 1 },
  { unique: true, partialFilterExpression: { clientId: { $type: 'string' } } }
);

export default mongoose.model('Message', messageSchema);
